// Checkout conversion fix: ensure paidEvents increment on successful payment
// This module intercepts the checkout completion webhook and forces a revenue event

const axios = require('axios');

module.exports = async function fixCheckoutConversion(req, res, next) {
  // Only act on successful checkout completion
  if (req.path === '/api/checkout/complete' && req.method === 'POST') {
    const { orderId, amount, currency } = req.body;
    if (orderId && amount > 0) {
      try {
        // Fire revenue event to internal analytics
        await axios.post('http://localhost:4000/api/revenue/event', {
          event: 'paidEvent',
          orderId,
          amount,
          currency: currency || 'USD',
          timestamp: new Date().toISOString()
        });
        console.log(`[checkoutConversionFix] paidEvent recorded for order ${orderId}`);
      } catch (err) {
        console.error('[checkoutConversionFix] Failed to record paidEvent:', err.message);
      }
    }
  }
  next();
};
